// Original model and teaching. Numerical estimates attributed in the source copy.
export const waterFamilies=[
 {id:'fresh-amount',label:'How much is fresh?'},{id:'fresh-store',label:'Where is most fresh water?'},
 {id:'other-share',label:'What belongs in Other?'},{id:'which-whole',label:'Which whole does the reader mean?'},
 {id:'drinking',label:'What does fresh tell us?'},{id:'two-trays',label:'One tray or two?'},
 {id:'ice-counts',label:'Does ice count?'},{id:'underground',label:'Water underground'}
];
const number=n=>Number.isInteger(n)?String(n):`${Math.floor(n)}½`;
const copies={
 welcome:'The storm has passed. Pip looks at the full millpond. “Water everywhere!” Dot brings two model trays to the Water Lab. “Let’s look at where Earth’s water waits.” Help make a diagram a visitor can read.',
 model:'A rounded teaching model based on published water estimates, not measurements made here. Model cups picture shares; they are not the real amounts you could carry or use.',
 zoom:'The freshwater tray is a zoom into the fresh part of the all-water tray. It has a new whole and a new scale. We have not added more water to Earth.',
 percent:'Percent means parts out of 100. In the freshwater model, 69 out of 100 cups is 69%. With 200 model cups, that same 69% is 138 cups. Always name the whole: freshwater is a different whole from all Earth’s water.',
 half:'Half a model cup is one of two equal parts. Two halves make one cup. In the hundred-cup all-water model, 97½ are saline and 2½ are fresh.',
 help:'Name the whole first. Read each row of its table, then set the matching bar to that many model cups. The source table stays available.',
 example:'A different tray has 10 model cups: half are blue, so 5 are blue. A tray of 20 with the same half share has 10 blue cups. The share stayed the same; the model amount changed.',
 goal:'This visitor can read your diagram and its whole. Keep exploring, or invite a different reader.',
 limit:'These rounded models close to their own totals. The freshwater Other category includes several stores, not just rivers and lakes. Fresh means low in dissolved salt; that label does not show that water is safe to drink.',
 support:'Tables, reservoir cards and model diagrams are available throughout. A matching graph or supplied answer does not establish independent reading, graph drawing, practical water testing or mastery.',
 sources:'Approximate distribution estimates: USGS Water Science School, based on Shiklomanov (1993), corroborated by NOAA JetStream. The saline model share is the complement of the approximate 2.5% freshwater share. Source freshwater shares 68.7%, 30.1% and about 1.2% are rounded here to 69, 30 and 1.',
 checks:{missing:'Some bars have not been entered yet. Zero is a number; a blank is still waiting.',total:'The entered bars do not add up to this model’s whole. Compare the total and the source table.',rows:'The total fits, but some rows differ from the source table. Compare their labels and values.',match:'These bars match this view’s own source table and whole.'}
};
const cards=[
 {id:'saline',title:'Saline water',text:'Saline means salty. Most saline water is in oceans. Some lakes and groundwater are salty too.',pictureDescription:'Ocean waves with a labeled saline-water card.'},
 {id:'ice',title:'Ice caps, glaciers and permanent snow',text:'Ice is water in solid form. These frozen stores hold most freshwater in this rounded model. The label does not include sea ice or every kind of frozen ground.',pictureDescription:'A mountain glacier and ice cap labeled as frozen freshwater.'},
 {id:'ground',title:'Fresh groundwater',text:'Below the water table, spaces in soil and rock are filled with water. That is the saturated zone. This table’s groundwater is there; it need not be an underground lake. Some groundwater is saline.',pictureDescription:'A cutaway with soil moisture above a water table and water-filled spaces below; groundwater is below the line.'},
 {id:'other',title:'Other freshwater',text:'This smaller group includes soil moisture above the water table, ground ice and permafrost, freshwater lakes, atmosphere, wetlands, rivers and water in living things. Each part is counted once. Other does not mean only rivers, only liquid, or water safe to drink.',pictureDescription:'Separate labeled small stores: soil moisture, frozen ground, a lake, air, wetland, river and a plant.'}
];
export function makeWaterSource(family='fresh-amount',cups=100){
 const index=waterFamilies.findIndex(f=>f.id===family);if(index<0||![100,200].includes(cups))return null;
 const factor=cups/100,totalHalf=cups*2,amount=2.5*factor;
 const views=[
  {id:'all',label:'All Earth’s water',whole:`${cups} model cups represent all Earth’s water`,totalHalf,
   description:'A tray for all water. Its saline and fresh parts together make the complete model whole.',
   rows:[{id:'saline',label:'Saline water',units:195*factor,detail:'Oceans plus other saline stores, including salty lakes and groundwater.'},{id:'fresh',label:'Freshwater',units:5*factor,detail:'All freshwater together, frozen and liquid; this is the part the other tray zooms into.'}]},
  {id:'fresh',label:'Freshwater only',whole:`${cups} model cups represent only Earth’s freshwater`,totalHalf,
   description:'A larger view of only the fresh part of the all-water model, not more water added to Earth.',
   rows:[{id:'ice',label:'Ice caps, glaciers, permanent snow',units:138*factor,detail:'Frozen freshwater in ice caps, glaciers and permanent snow.'},{id:'ground',label:'Fresh groundwater',units:60*factor,detail:'Fresh water in the saturated zone below the water table.'},{id:'other',label:'All other freshwater',units:2*factor,detail:'Several other stores, including ground ice, soil moisture, freshwater lakes, air, wetlands, rivers and living things.'}]}
 ];
 const definitions={
  'fresh-amount':{view:'all',prompt:`How many of these ${cups} all-water model cups are fresh?`,context:'Use the freshwater row in the all-water table.',fit:`${number(amount)} model cups`,wrong:[`${25*factor} model cups`,`${number(97.5*factor)} model cups`],feedback:['Check the place value. The fresh share is much smaller than one quarter.','That is the saline row. Read the fresh row.'],explain:`The fresh row is ${number(amount)} out of ${cups} model cups.`,hint:'Read the row named Freshwater, not Saline water.'},
  'fresh-store':{view:'fresh',prompt:'Which category holds the most in this freshwater model?',context:'Read the freshwater-only table. Its whole is freshwater, not all water.',fit:'Ice caps, glaciers and permanent snow',wrong:['Fresh groundwater','Rivers and lakes alone'],feedback:['Groundwater is a large store, but the frozen-store row is larger.','Rivers and lakes are part of the small Other group.'],explain:'The frozen-store category is the largest in this freshwater whole.',hint:'Compare the values in the freshwater-only rows.'},
  'other-share':{view:'fresh',prompt:'What does Other freshwater include?',context:'The Other card explains what is counted in that small row.',fit:'Several smaller stores: ground ice, soil moisture, rivers',wrong:['Only rivers and lakes, with no ground ice or soil moisture','The cards give no examples of which smaller stores it contains'],feedback:['Rivers and lakes are included, but so are several other stores.','The Other card names ground ice, soil moisture, air and several more stores.'],explain:'Other combines several smaller stores; it is not a name for rivers alone.',hint:'Read the Other reservoir card. Look for both frozen and liquid examples.'},
  'which-whole':{view:'fresh',prompt:'A visitor says, “The 69% frozen-store share is of all Earth’s water.” Which reply fits?',context:'The freshwater-only diagram has a different whole from the all-water diagram.',fit:'The 69% is of freshwater, a smaller whole',wrong:['The 69% is of all Earth’s water','The tables give no whole, so we cannot tell'],feedback:['That swaps the freshwater whole for the all-water whole.','Each table names its whole. The freshwater title supplies the evidence.'],explain:'A percentage is a share of its named whole. Zooming changes which water set is the whole.',hint:'Read the whole label above the freshwater diagram.'},
  drinking:{view:'all',prompt:'Does the label fresh prove that water is safe to drink?',context:'This is a distribution model. It does not test water quality.',fit:'No. Low salt does not establish drinking safety',wrong:['Yes. Every freshwater store is safe to drink','No freshwater can be liquid'],feedback:['The fresh label describes salt content, not a water-quality test.','Freshwater can be liquid or frozen. The label does not answer drinking safety.'],explain:'Fresh means low dissolved salt. This model does not establish safe drinking water.',hint:'Separate the salt-content label from a safety test.'},
  'two-trays':{view:'all',prompt:'A model grows from 100 to 200 cups with the same fresh share. What changes?',context:'In this model: 100 all-water cups contain 2½ fresh cups; 200 contain 5. These are two model scales for the same Earth.',fit:'The model’s fresh amount doubles from 2½ to 5 cups',wrong:['The model’s fresh amount stays at 2½ cups','The real amount of freshwater on Earth doubles'],feedback:['The fresh share stays the same, but the larger model has twice the number of cups.','We changed our model’s scale, not the real Earth.'],explain:'Equal shares of different model totals can represent different model amounts.',hint:'Compare the two supplied model totals and fresh amounts.'},
  'ice-counts':{view:'fresh',prompt:'Should we leave glacier water out because it is frozen?',context:'The source table includes a frozen-store category in its freshwater whole.',fit:'No. Ice is still water and is counted here',wrong:['Yes. Freshwater means liquid water only','The table gives no evidence that ice is counted'],feedback:['Freshwater can be solid ice as well as liquid.','The ice-cap/glacier row explicitly counts that water.'],explain:'The freshwater whole includes frozen water. The table names which frozen stores it counts.',hint:'Find the frozen-store row in the freshwater table.'},
  underground:{view:'fresh',prompt:'Does groundwater have to be fresh?',context:'The cards describe both fresh and saline groundwater; the freshwater table counts the fresh part.',fit:'Some groundwater is fresh and some is saline',wrong:['Every underground water store is fresh','There is no evidence of fresh groundwater in the model'],feedback:['Being underground does not determine salt content.','The table explicitly has a fresh-groundwater row.'],explain:'The freshwater diagram includes only fresh groundwater. Other groundwater belongs to saline water in the all-water model.',hint:'Compare the groundwater card with the fresh-groundwater row.'}
 };
 const d=definitions[family],options=[{text:d.fit,feedback:d.explain,fit:true},...d.wrong.map((text,i)=>({text,feedback:d.feedback[i],fit:false}))],rotation=(index+(cups===200?1:0))%3,ordered=[...options.slice(rotation),...options.slice(0,rotation)];
 const examples={
  'fresh-amount':copies.example,
  'fresh-store':'A different, invented button tray holds 70 blue, 20 red and 10 green buttons. Blue is the largest row because 70 is larger than 20 or 10.',
  'other-share':'In a make-believe toolbox, Other combines thread, buttons and ribbon. Calling it only ribbon would leave out parts the source lists.',
  'which-whole':copies.example,
  drinking:'A model jar’s label says low salt. That describes one property. It does not say that the contents have been checked for drinking safety.',
  'two-trays':copies.example,
  'ice-counts':'A labeled ice cube is frozen water. Putting it in the frozen group does not mean leaving it out of a model of water.',
  underground:'Two labeled model jars, fresh and saline, could be in the same cupboard. Their location alone does not tell us which salt label fits.'
 };
 const selectedCopy=structuredClone(copies);if(cups===200)selectedCopy.half='Half a model cup is one of two equal parts; two halves make one cup. This 200-cup all-water model has 195 saline and 5 fresh cups. The 100-cup version has 97½ saline and 2½ fresh cups.';
 const question={id:family,view:d.view,context:d.context,prompt:d.prompt,key:['a','b','c'][ordered.findIndex(x=>x.fit)],choices:ordered.map((x,i)=>({id:['a','b','c'][i],text:x.text,feedback:x.feedback})),hint:d.hint,example:examples[family],together:`First name the whole. Then read the relevant source row or card. ${d.explain}`};
 return {version:1,id:`${family}-${cups}`,title:'Hundred Cups',family,cups,views,cards:structuredClone(cards),question,copy:selectedCopy,sources:[{label:'USGS · Where is Earth’s Water?',url:'https://www.usgs.gov/water-science-school/science/where-earths-water'},{label:'NOAA · What a Cycle!',url:'https://www.noaa.gov/jetstream/max-what-cycle'},{label:'CDC · Natural water and drinking safety',url:'https://www.cdc.gov/drinking-water/prevention/water-treatment-hiking-camping-traveling.html'}]};
}
export const waterSource=makeWaterSource();
